/**
 * @module features/financeiro
 *
 * Feature financeira: livro caixa, DRE, balanço patrimonial,
 * contabilidade (journals/moves), contas a pagar/receber e analytics.
 */

export { default as FinanceiroPage } from './ui/Financeiro.page';
export { default as LivroCaixaPage } from './ui/LivroCaixa';
export { FinanceReportsModal } from './ui/FinanceReportsModal';
export { AccountingDashboard } from './ui/AccountingDashboard';
export { DREReport } from './ui/DREReport';
export { BalanceSheetReport } from './ui/BalanceSheetReport';
export { FinancialOverview } from './ui/FinancialOverview';
export { CategoryDashboard } from './ui/CategoryDashboard';
export { useAccounting } from './model/useAccounting';
export { useCashBook } from './model/useCashBook';
export { useFinancialAccounts } from './model/useFinancialAccounts';
export { ConsultarNcms } from './ui/ConsultarNcms';
export { default as CmvPage } from './ui/Cmv.page';
export { default as CmvConfiguratorPage } from './ui/CmvConfigurator.page';
export { useCmvFichas } from './model/useCmvFichas';
export { useCmvGraph } from './model/useCmvGraph';

