1	import { useEffect, useMemo, useRef, useState } from "react";
2	import { printHTML } from '@/shared/lib/print';
3	import { FileText, Plus, Search, Upload, Pencil, Trash2, Printer, ArrowLeft } from "lucide-react";
4	import { Card, CardContent, CardHeader, CardTitle } from "@/shared/ui/card";
5	import { Button } from "@/shared/ui/button";
6	import { Input } from "@/shared/ui/input";
7	import { Label } from "@/shared/ui/label";
8	import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/shared/ui/select";
9	import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/shared/ui/dialog";
10	import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/shared/ui/table";
11	import { toast } from "@/shared/ui/use-toast";
12	import { supabase } from "@/integrations/supabase/client";
13	import * as XLSX from "xlsx";
14	import { PermissionBlur } from "@/shared/ui/PermissionBlur";
15	import { usePermissions } from "@/shared/hooks/usePermissions";
16	import { useMiaNCMActions } from "@/features/mia/model/hooks";
17	
18	type Categoria =
19	  | "insumos"
20	  | "embalagens"
21	  | "descartaveis"
22	  | "bebidas"
23	  | "mercearia"
24	  | "material_limpeza"
25	  | "insumos_momma_brunch"
26	  | "finalizados";
27	
28	type NcmProduto = {
29	  id: number;
30	  produto_nome: string;
31	  ncm: string;
32	  categoria: Categoria;
33	  descricao: string | null;
34	  custo: number | null;
35	  loja_id: number | null;
36	  created_at: string | null;
37	  updated_at: string | null;
38	};
39	
40	const categoriaLabels: Record<Categoria, string> = {
41	  insumos: "Insumos",
42	  embalagens: "Embalagens",
43	  descartaveis: "Descartáveis",
44	  bebidas: "Bebidas",
45	  mercearia: "Mercearia",
46	  material_limpeza: "Material de Limpeza",
47	  insumos_momma_brunch: "Insumos Momma Brunch",
48	  finalizados: "Produtos Finalizados",
49	};
50	
51	function normalizeCategoria(value: string): Categoria | null {
52	  const v = value.trim().toLowerCase();
53	  if (["insumo", "insumos"].includes(v)) return "insumos";
54	  if (["insumos momma brunch", "insumos momma"].includes(v)) return "insumos_momma_brunch";
55	  if (["embalagem", "embalagens"].includes(v)) return "embalagens";
56	  if (["descartavel", "descartáveis", "descartaveis"].includes(v)) return "descartaveis";
57	  if (["bebida", "bebidas"].includes(v)) return "bebidas";
58	  if (["mercearia"].includes(v)) return "mercearia";
59	  if (["material de limpeza", "limpeza"].includes(v)) return "material_limpeza";
60	  if (["finalizado", "finalizados", "produto finalizado", "produtos finalizados"].includes(v)) return "finalizados";
61	  return null;
62	}
63	
64	interface ConsultarNcmsProps {
65	  onBack?: () => void;
66	}
67	
68	export function ConsultarNcms({ onBack }: ConsultarNcmsProps) {
69	  const [items, setItems] = useState<NcmProduto[]>([]);
70	  const [loading, setLoading] = useState(false);
71	  const [categoriaFilter, setCategoriaFilter] = useState<Categoria | "all">("all");
72	  const [ncmFilter, setNcmFilter] = useState<"all" | "com" | "sem">("all");
73	  const [searchTerm, setSearchTerm] = useState("");
74	  const [isModalOpen, setIsModalOpen] = useState(false);
75	  const [editingItem, setEditingItem] = useState<NcmProduto | null>(null);
76	
77	  const [formProduto, setFormProduto] = useState("");
78	  const [formNcm, setFormNcm] = useState("");
79	  const [formCategoria, setFormCategoria] = useState<Categoria>("insumos");
80	  const [formDescricao, setFormDescricao] = useState("");
81	  const [formCusto, setFormCusto] = useState("");
82	  const fileInputRef = useRef<HTMLInputElement>(null);
83	  const { canViewNCM } = usePermissions();
84	  const hasAccess = canViewNCM();
85	
86	  useMiaNCMActions({
87	    setCategoriaFilter: (v: string) => setCategoriaFilter(v as Categoria | "all"),
88	    setSearchTerm,
89	  });
90	
91	  useEffect(() => {
92	    fetchItems();
93	  }, []);
94	
95	  const fetchItems = async () => {
96	    try {
97	      setLoading(true);
98	      const { data, error } = await supabase
99	        .from("ncm_produtos")
100	        .select("*")
101	        .order("produto_nome", { ascending: true });
102	      if (error) throw error;
103	      const arr = (data || []) as NcmProduto[];
104	      const dedup = new Map<string, NcmProduto>();
105	      for (const it of arr) {
106	        const existing = dedup.get(it.produto_nome);
107	        if (!existing || (!existing.ncm && it.ncm)) {
108	          dedup.set(it.produto_nome, it);
109	        }
110	      }
111	      setItems(Array.from(dedup.values()));
112	    } catch (error) {
113	      console.error("Erro ao buscar NCMs:", error);
114	      toast({ title: "Erro ao carregar", description: "Não foi possível carregar os NCMs" });
115	    } finally {
116	      setLoading(false);
117	    }
118	  };
119	
120	  const filteredItems = useMemo(() => {
121	    const filtered = items
122	      .filter((it) => categoriaFilter === "all" || it.categoria === categoriaFilter)
123	      .filter((it) => (ncmFilter === "all" ? true : ncmFilter === "com" ? Boolean(it.ncm) : !it.ncm))
124	      .filter((it) =>
125	        searchTerm ? it.produto_nome.toLowerCase().includes(searchTerm.toLowerCase()) || (it.ncm || "").includes(searchTerm) : true
126	      );
127	
128	    const dedup = new Map<string, NcmProduto>();
129	    for (const it of filtered) {
130	      const prev = dedup.get(it.produto_nome);
131	      if (!prev || (!prev.ncm && it.ncm)) dedup.set(it.produto_nome, it);
132	    }
133	    return Array.from(dedup.values());
134	  }, [items, categoriaFilter, ncmFilter, searchTerm]);
135	
136	  const handlePrint = () => {
137	    try {
138	      const ordered: Categoria[] = [
139	        'insumos',
140	        'embalagens',
141	        'descartaveis',
142	        'bebidas',
143	        'mercearia',
144	        'material_limpeza',
145	        'insumos_momma_brunch',
146	        'finalizados',
147	      ];
148	
149	      const map = new Map<Categoria, NcmProduto[]>();
150	      for (const it of filteredItems) {
151	        const arr = map.get(it.categoria) || [];
152	        arr.push(it);
153	        map.set(it.categoria, arr);
154	      }
155	
156	      const groups = ordered
157	        .map((cat) => {
158	          const arr = map.get(cat);
159	          if (!arr || arr.length === 0) return null;
160	          return [cat, arr.sort((a, b) => a.produto_nome.localeCompare(b.produto_nome))] as [Categoria, NcmProduto[]];
161	        })
162	        .filter((x): x is [Categoria, NcmProduto[]] => Boolean(x));
163	
164	      const isSingle = groups.length === 1;
165	
166	      const pages: [Categoria, NcmProduto[]][][] = [];
167	      if (isSingle) {
168	        pages.push(groups);
169	      } else {
170	        for (let i = 0; i < groups.length; i += 2) {
171	          pages.push(groups.slice(i, i + 2));
172	        }
173	      }
174	
175	      const pagesHtml = pages
176	        .map((page) => {
177	          const colsClass = isSingle ? 'grid-1' : 'grid-2';
178	          const catsHtml = page
179	            .map(([cat, arr]) => {
180	              const rows = arr
181	                .map(
182	                  (item) => `
183	                  <tr>
184	                    <td class="cell name">${item.produto_nome}</td>
185	                    <td class="cell ncm">${formatNcm(item.ncm || '')}</td>
186	                    <td class="cell valor">${formatCurrency(item.custo)}</td>
187	                  </tr>
188	                `
189	                )
190	                .join('');
191	              return `
192	                <div class="category">
193	                  <div class="category-title">${categoriaLabels[cat].toUpperCase()}</div>
194	                  <table class="table">
195	                    <thead>
196	                      <tr>
197	                        <th class="head">Produto</th>
198	                        <th class="head">NCM</th>
199	                        <th class="head">Valor</th>
200	                      </tr>
201	                    </thead>
202	                    <tbody>${rows}</tbody>
203	                  </table>
204	                </div>
205	              `;
206	            })
207	            .join('');
208	          return `
209	            <div class="page">
210	              <div class="${colsClass}">${catsHtml}</div>
211	            </div>
212	          `;
213	        })
214	        .join('');
215	
216	      const html = `<!DOCTYPE html>
217	      <html>
218	      <head>
219	        <title>Lista de NCMs</title>
220	        <style>
221	          @page { margin: 12mm; size: A4; }
222	          * { margin: 0; padding: 0; box-sizing: border-box; }
223	          body { font-family: Arial, sans-serif; font-size: 11px; line-height: 1.25; }
224	          .header { background-color: #4CAF50; color: white; text-align: center; padding: 8px; font-weight: bold; font-size: 14px; }
225	          .header-title { letter-spacing: 0.5px; }
226	          .grid-1 { display: grid; grid-template-columns: 1fr; gap: 8px; margin-top: 10px; }
227	          .grid-2 { display: grid; grid-template-columns: repeat(2, 1fr); gap: 8px; margin-top: 10px; }
228	          .category { border: 1px solid #333; }
229	          .category-title { padding: 6px 8px; background-color: #2E7D32; color: white; font-weight: bold; letter-spacing: 0.5px; }
230	          .table { width: 100%; border-collapse: collapse; }
231	          .head { background-color: #f0f0f0; border: 1px solid #333; padding: 4px; text-align: left; font-size: 10px; }
232	          .cell { border: 1px solid #333; padding: 3px 6px; font-size: 10px; }
233	          .name { font-weight: bold; }
234	          .ncm { text-align: left; }
235	          .valor { text-align: left; }
236	          .page { page-break-after: always; break-after: page; }
237	          .page:last-child { page-break-after: auto; break-after: auto; }
238	          @media print { body { -webkit-print-color-adjust: exact; } }
239	        </style>
240	      </head>
241	      <body>
242	        <div class="header"><span class="header-title">MOMMA DOCES SAUDÁVEIS</span></div>
243	        ${pagesHtml}
244	      </body>
245	      </html>`;
246	
247	      printHTML(html, { title: 'NCMs - Momma' });
248	    } catch (e) { console.error('[ConsultarNcms] handlePrint error:', e); }
249	  };
250	
251	  const formatNcm = (n: string | null) => {
252	    if (!n) return "";
253	    const s = String(n).replace(/[^0-9]/g, "");
254	    if (s.length === 8) return `${s.slice(0,4)}.${s.slice(4,6)}.${s.slice(6,8)}`;
255	    return n;
256	  };
257	
258	  const formatCurrency = (v: number | null) => {
259	    if (v == null) return "";
260	    try {
261	      return v.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
262	    } catch {
263	      return String(v);
264	    }
265	  };
266	
267	  const parseCurrency = (s: string) => {
268	    const t = s.trim();
269	    if (!t) return null;
270	    const v = t.replace(/[^0-9,.-]/g, "").replace(/\./g, "").replace(/,/g, ".");
271	    const n = Number(v);
272	    return Number.isFinite(n) ? n : null;
273	  };
274	
275	  const openCreate = () => {
276	    setEditingItem(null);
277	    setFormProduto("");
278	    setFormNcm("");
279	    setFormCategoria("insumos");
280	    setFormDescricao("");
281	    setFormCusto("");
282	    setIsModalOpen(true);
283	  };
284	
285	  const openEdit = (item: NcmProduto) => {
286	    setEditingItem(item);
287	    setFormProduto(item.produto_nome);
288	    setFormNcm(item.ncm);
289	    setFormCategoria(item.categoria);
290	    setFormDescricao(item.descricao || "");
291	    setFormCusto(item.custo != null ? String(item.custo) : "");
292	    setIsModalOpen(true);
293	  };
294	
295	  const handleSave = async () => {
296	    try {
297	      if (!formProduto.trim() || !formNcm.trim()) {
298	        toast({ title: "Campos obrigatórios", description: "Preencha produto e NCM." });
299	        return;
300	      }
301	      const payload = {
302	        produto_nome: formProduto.trim(),
303	        ncm: formNcm.trim(),
304	        categoria: formCategoria,
305	        descricao: formDescricao.trim() || null,
306	        custo: parseCurrency(formCusto),
307	      };
308	
309	      if (editingItem) {
310	        const { error } = await supabase
311	          .from("ncm_produtos")
312	          .update(payload)
313	          .eq("produto_nome", editingItem.produto_nome);
314	        if (error) throw error;
315	        toast({ title: "Atualizado", description: "Registro atualizado com sucesso" });
316	      } else {
317	        const { error } = await supabase.from("ncm_produtos").insert(payload);
318	        if (error) throw error;
319	        toast({ title: "Adicionado", description: "Registro criado com sucesso" });
320	      }
321	      setIsModalOpen(false);
322	      fetchItems();
323	    } catch (error) {
324	      console.error("Erro ao salvar NCM:", error);
325	      toast({ title: "Erro", description: "Não foi possível salvar o registro" });
326	    }
327	  };
328	
329	  const handleDelete = async (item: NcmProduto) => {
330	    try {
331	      const { error } = await supabase.from("ncm_produtos").delete().eq("produto_nome", item.produto_nome);
332	      if (error) throw error;
333	      toast({ title: "Removido", description: "Registro excluído" });
334	      fetchItems();
335	    } catch (error) {
336	      console.error("Erro ao excluir NCM:", error);
337	      toast({ title: "Erro", description: "Não foi possível excluir" });
338	    }
339	  };
340	
341	  const handleImportClick = () => {
342	    fileInputRef.current?.click();
343	  };
344	
345	  const handleFileChange: React.ChangeEventHandler<HTMLInputElement> = async (e) => {
346	    try {
347	      const file = e.target.files?.[0];
348	      if (!file) return;
349	      const reader = new FileReader();
350	      reader.onload = async (ev) => {
351	        const data = new Uint8Array(ev.target?.result as ArrayBuffer);
352	        const workbook = XLSX.read(data, { type: "array" });
353	        const sheetName = workbook.SheetNames[0];
354	        const sheet = workbook.Sheets[sheetName];
355	        const rows: ImportRow[] = XLSX.utils.sheet_to_json(sheet, { defval: "" }) as ImportRow[];
356	
357	        const toUpsert = rows
358	          .map((r) => {
359	            const nome = String(r.produto ?? r.produto_nome ?? r.nome ?? "").trim();
360	            const ncm = String(r.ncm ?? "").trim();
361	            const categoriaRaw = String(r.categoria ?? r.tipo ?? "").trim();
362	            const cat = normalizeCategoria(categoriaRaw);
363	            const descricao = String(r.descricao ?? "").trim();
364	            if (!nome || !ncm || !cat) return null;
365	            return {
366	              produto_nome: nome,
367	              ncm,
368	              categoria: cat,
369	              descricao: descricao || null,
370	            } as const;
371	          })
372	          .filter(Boolean) as Array<{ produto_nome: string; ncm: string; categoria: Categoria; descricao: string | null }>;
373	
374	        if (toUpsert.length === 0) {
375	          toast({ title: "Arquivo vazio", description: "Não há registros válidos para importar" });
376	          return;
377	        }
378	
379	        const { error } = await supabase
380	          .from("ncm_produtos")
381	          .upsert(toUpsert.map(r => ({ ...r, loja_id: null })), { onConflict: "produto_nome,loja_id" });
382	        if (error) throw error;
383	
384	        // Atualizar registros existentes (todas lojas) para refletir dados importados
385	        for (const r of toUpsert) {
386	          await supabase
387	            .from("ncm_produtos")
388	            .update({ ncm: r.ncm, categoria: r.categoria, descricao: r.descricao })
389	            .eq("produto_nome", r.produto_nome);
390	        }
391	        toast({ title: "Importado", description: `${toUpsert.length} registros importados/atualizados` });
392	        fetchItems();
393	      };
394	      reader.readAsArrayBuffer(file);
395	      // Reset input to allow same file re-upload
396	      e.target.value = "";
397	    } catch (error) {
398	      console.error("Erro ao importar arquivo:", error);
399	      toast({ title: "Erro na importação", description: "Verifique o arquivo e tente novamente" });
400	    }
401	  };
402	
403	  return (
404	    <PermissionBlur hasPermission={hasAccess} moduleName="Financeiro" permissionName="view_ncm">
405	    <div className="min-h-screen max-w-full overflow-x-hidden px-3 sm:px-4 md:px-6 space-y-6 pb-24 print:hidden">
406	      {onBack && (
407	        <Button variant="ghost" onClick={onBack} className="gap-2 -ml-2 text-[#57715B] hover:bg-[#57715B]/10">
408	          <ArrowLeft className="h-4 w-4" />
409	          Voltar
410	        </Button>
411	      )}
412	      <div className="flex flex-col sm:flex-row sm:justify-between sm:items-center gap-3">
413	        <div className="text-center sm:text-left">
414	          <h1 className="text-2xl font-bold tracking-tight text-[#2D362E] dark:text-[#E6DCCF]">Consultar NCMs</h1>
415	          <p className="text-xs uppercase tracking-widest text-muted-foreground">Produtos e seus respectivos códigos NCM</p>
416	        </div>
417	        <div className="flex flex-wrap gap-2 sm:gap-3 w-full sm:w-auto items-center">
418	          <Button data-mia-action="open-create" onClick={openCreate} className="rounded-xl bg-[#57715B] hover:bg-[#465b49] text-white shadow-sm gap-2">
419	            <Plus className="h-4 w-4" />
420	            Novo registro
421	          </Button>
422	          <Button data-mia-action="import-click" variant="outline" onClick={handleImportClick} className="rounded-xl bg-white/60 hover:bg-[#57715B]/10 text-[#57715B] border-[#57715B]/20 gap-2">
423	            <Upload className="h-4 w-4" />
424	            Importar CSV/XLSX
425	          </Button>
426	          <Button data-mia-action="print" variant="outline" onClick={handlePrint} className="rounded-xl bg-white/60 hover:bg-[#57715B]/10 text-[#57715B] border-[#57715B]/20 gap-2">
427	            <Printer className="h-4 w-4" />
428	            Imprimir
429	          </Button>
430	          <input ref={fileInputRef} type="file" accept=".csv, application/vnd.openxmlformats-officedocument.spreadsheetml.sheet, application/vnd.ms-excel" className="hidden" onChange={handleFileChange} />
431	        </div>
432	      </div>
433	
434	      <Card className="rounded-2xl border-[#57715B]/10 bg-white/60 dark:bg-[#1A1A1A]/60 backdrop-blur-xl shadow-sm">
435	        <CardHeader>
436	          <CardTitle className="flex items-center gap-2 text-lg">
437	            <FileText className="h-5 w-5" /> Lista de NCMs
438	          </CardTitle>
439	        </CardHeader>
440	        <CardContent>
441	          <div className="grid grid-cols-1 md:grid-cols-4 gap-3 mb-4">
442	            <div>
443	              <Label className="text-xs">Filtrar por categoria</Label>
444	              <Select value={categoriaFilter} onValueChange={(v) => setCategoriaFilter(v as Categoria | "all")}>
445	                <SelectTrigger className="h-8 rounded-xl border-[#57715B]/20 focus:border-[#57715B] bg-white/70 dark:bg-black/20">
446	                  <SelectValue placeholder="Todas" />
447	                </SelectTrigger>
448	                <SelectContent className="rounded-xl border-[#57715B]/10 bg-white/90 dark:bg-[#1A1A1A]/90 backdrop-blur-xl">
449	                  <SelectItem value="all">Todas</SelectItem>
450	                  <SelectItem value="insumos">Insumos</SelectItem>
451	                  <SelectItem value="embalagens">Embalagens</SelectItem>
452	                  <SelectItem value="descartaveis">Descartáveis</SelectItem>
453	                  <SelectItem value="bebidas">Bebidas</SelectItem>
454	                  <SelectItem value="mercearia">Mercearia</SelectItem>
